import { expect, test, uniqueName } from "../../fixtures";

test("documents from another tenant are invisible", { tag: "@DOC-07" }, async ({ apiAs }) => {
  // Arrange: a draft vendor for the signed-in member (Background)
  const member = await apiAs("member");
  const ownVendor = await member.post("/api/vendors", {
    data: { name: uniqueName("Northwind Draft"), category: "services", contact_email: "ops@northwind.example" },
  });
  expect(ownVendor.status(), await ownVendor.text()).toBe(201);
  expect((await ownVendor.json()).status).toBe("draft");

  // Arrange: a document that exists in the Globex tenant
  const otherTenant = await apiAs("otherTenant");
  const globexVendor = await otherTenant.post("/api/vendors", {
    data: { name: uniqueName("Globex Only"), category: "other", contact_email: "x@globex.example" },
  });
  expect(globexVendor.status(), await globexVendor.text()).toBe(201);
  const globexVendorId = ((await globexVendor.json()) as { id: string }).id;

  const upload = await otherTenant.post(`/api/vendors/${globexVendorId}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.txt", mimeType: "text/plain", buffer: Buffer.from("Legal Name: Globex\n") },
    },
  });
  expect(upload.status(), await upload.text()).toBe(201);
  const documentId = ((await upload.json()) as { id: string }).id;

  // Act: the Northwind member requests the Globex document by id
  const response = await member.get(`/api/documents/${documentId}`);

  // Assert
  expect(response.status(), await response.text()).toBe(404);
  const body = await response.json();
  expect(body.error.code, JSON.stringify(body)).toBe("document_not_found");
});
